// Interface commune des états — chaque état implémente ce qu'il fait
export abstract class {State}State {
  abstract getName(): string
  // Ajoute ici les méthodes communes à tous les états
  onEnter(context: {State}Context): void {}
  onExit(context: {State}Context):  void {}
}

