export class {State}SubmittingState extends {State}State {
  getName() { return 'submitting' }
  onEnter(context: {State}Context): void {
    // Ajoute ici ce qui se passe lors de la soumission
    // context.submit()
  }
}

export class {State}ErrorState extends {State}State {
  constructor(private message: string) { super() }
  getName() { return 'error' }
  getError() { return this.message }
}

// Gestionnaire de contexte — orchestre les transitions
export class {State}Machine {
  private state: {State}State

  constructor(
    initialState: {State}State,
    private context: {State}Context
  ) {
    this.state = initialState
    this.state.onEnter(context)
  }

  transition(newState: {State}State): void {
    this.state.onExit(this.context)
    this.state = newState
    this.state.onEnter(this.context)
  }

  getStateName(): string { return this.state.getName() }
  isIn(name: string):    boolean { return this.state.getName() === name }
  getCurrent():          {State}State { return this.state }
}

// composables/{state}/use{State}Machine.ts
import {
  {State}Machine,
  {State}ViewState,
  {State}EditState,
  {State}SubmittingState,
  {State}ErrorState
} from '~/utils/states/{state}/{State}States'
import type { {State}Context } from '~/utils/states/{state}/{State}States'

export const use{State}Machine = (initialData: Record<string, unknown> = {}) => {
  const data    = reactive({ ...initialData })
  const stateName = ref('view')

  const context: {State}Context = {
    // Ajoute ici l'implémentation du contexte
  }

  const machine = new {State}Machine(new {State}ViewState(), context)

  const transition = (newState: InstanceType<typeof {State}ViewState>) => {
    machine.transition(newState)
    stateName.value = machine.getStateName()
  }

  return {
    data,
    stateName: readonly(stateName),
    isView:       computed(() => machine.isIn('view')),
    isEdit:       computed(() => machine.isIn('edit')),
    isSubmitting: computed(() => machine.isIn('submitting')),
    isError:      computed(() => machine.isIn('error')),
    toView:       () => transition(new {State}ViewState()),
    toEdit:       () => transition(new {State}EditState()),
    toSubmitting: () => transition(new {State}SubmittingState()),
    toError:      (msg: string) => transition(new {State}ErrorState(msg) as any)
  }
}

// tests/utils/states/{state}/{State}States.spec.ts
import { describe, it, expect, vi } from 'vitest'
import {
  {State}Machine,
  {State}ViewState,
  {State}EditState,
  {State}SubmittingState,
  {State}ErrorState
} from '~/utils/states/{state}/{State}States'

const mockContext = { /* Ajoute ici le contexte mock */ }

describe('{State}Machine', () => {

  it('démarre dans l\'état initial', () => {
    const m = new {State}Machine(new {State}ViewState(), mockContext)
    expect(m.getStateName()).toBe('view')
  })

  it('transition() change d\'état', () => {
    const m = new {State}Machine(new {State}ViewState(), mockContext)
    m.transition(new {State}EditState())
    expect(m.getStateName()).toBe('edit')
  })

  it('isIn() retourne true pour l\'état courant', () => {
    const m = new {State}Machine(new {State}ViewState(), mockContext)
    expect(m.isIn('view')).toBe(true)
    expect(m.isIn('edit')).toBe(false)
  })

  it('onEnter() est appelé lors d\'une transition', () => {
    const enterSpy = vi.spyOn({State}EditState.prototype, 'onEnter')
    const m        = new {State}Machine(new {State}ViewState(), mockContext)
    m.transition(new {State}EditState())
    expect(enterSpy).toHaveBeenCalledWith(mockContext)
  })

  it('{State}ErrorState expose le message d\'erreur', () => {
    const errState = new {State}ErrorState('Erreur de réseau')
    expect(errState.getError()).toBe('Erreur de réseau')
    expect(errState.getName()).toBe('error')
  })

})
